import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.BkFmai_x.js";const u=JSON.parse('{"title":"Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1784290844000}'),i={name:"guide/security.md"};function s(n,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h1><p>VaultGuard is <strong>zero-knowledge</strong>: your master password never leaves the device, is never written to disk, and is never sent to the server or API. It exists only long enough, in memory, to derive your keys. A stolen database, backup file or sync payload is useless without it. Every front-end (WPF, Blazor, MAUI, API, browser extension) shares the same <code>VaultGuard.Crypto</code> core, so these guarantees hold identically wherever you sign in - including the standalone WPF desktop app&#39;s local SQLite vault.</p><h2 id="key-derivation" tabindex="-1">Key derivation <a class="header-anchor" href="#key-derivation" aria-label="Permalink to &quot;Key derivation&quot;">​</a></h2><p><strong>PBKDF2-HMAC-SHA256, 600,000 iterations</strong> (the OWASP 2024 recommendation) derives a 256-bit master key from your master password and a per-user, cryptographically-random 32-byte salt. The iteration count is deliberately expensive to brute-force.</p><p><strong>Argon2id</strong> is also supported as a memory-hard alternative via a self-describing hash format (<code>$argon2id$...</code>) - authentication hashes can upgrade to Argon2id while existing PBKDF2 vaults keep verifying unchanged, since the format is auto-detected in the shared core.</p><p><strong>HKDF-SHA256</strong> then derives independent, purpose-specific sub-keys (encryption, authentication, backup, ...) from the master key, so a leak of one sub-key never exposes the others.</p><h2 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h2><p>Every secret - passwords, notes, card numbers, TOTP seeds, custom fields - is sealed with <strong>AES-256-GCM authenticated encryption</strong>: a fresh 96-bit random nonce per encryption, a 128-bit authentication tag, and rejection on decrypt if anything was tampered with. Nothing is ever stored with a static IV or an unauthenticated cipher mode.</p><h2 id="authentication-is-separate-from-encryption" tabindex="-1">Authentication is separate from encryption <a class="header-anchor" href="#authentication-is-separate-from-encryption" aria-label="Permalink to &quot;Authentication is separate from encryption&quot;">​</a></h2><p>The value stored for login is an <strong>authentication hash</strong> derived from the master key - not the master password, and not the encryption key itself (Bitwarden-style separation). Because it&#39;s a one-way derivative, the database can verify you without ever holding anything capable of decrypting your vault.</p><h2 id="operational-hardening" tabindex="-1">Operational hardening <a class="header-anchor" href="#operational-hardening" aria-label="Permalink to &quot;Operational hardening&quot;">​</a></h2><ul><li><strong>In-memory hygiene</strong> - the derived master key is zeroed with <code>Array.Clear</code> as soon as it&#39;s no longer needed; intermediate key-material buffers are wiped the same way.</li><li><strong>Constant-time comparisons</strong> - all security-sensitive verification (auth hashes, passcode hashes, 2FA/ TOTP codes, hashed recovery codes) uses <code>CryptographicOperations.FixedTimeEquals</code>, so response timing can&#39;t leak bytes.</li><li><strong>Two-factor &amp; recovery codes</strong> - TOTP support; recovery codes are hashed and single-use, never stored in plaintext.</li><li><strong>Passkeys</strong> - WebAuthn/FIDO2 sign-in, including a software authenticator for the browser extension.</li><li><strong>&quot;Remember this device&quot;</strong> - the cached credential lives in the platform&#39;s secure store, never as plaintext: Windows DPAPI (WPF), Keychain/Keystore (MAUI), <code>ProtectedLocalStorage</code> (Blazor web).</li><li><strong>Encrypted backups</strong> - local, NAS/SMB, FTP/FTPS, OneDrive and Google Drive backups are encrypted on the device before upload; those targets only ever see ciphertext.</li><li><strong>Brute-force protection</strong> - the API rate-limits requests (a global per-IP limit plus a stricter limit on authentication endpoints) and enforces account lockout after repeated failed sign-ins.</li><li><strong>Transport</strong> - HTTPS with an explicit CORS allow-list; the API additionally gates every request with bearer-token auth and an API-key middleware.</li></ul><h2 id="what-s-stored-vs-never-stored" tabindex="-1">What&#39;s stored vs. never stored <a class="header-anchor" href="#what-s-stored-vs-never-stored" aria-label="Permalink to &quot;What&#39;s stored vs. never stored&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stored (safe)</th><th>Never stored</th></tr></thead><tbody><tr><td>Per-user random salt (32 bytes)</td><td>❌ Master password (plaintext or reversible)</td></tr><tr><td>Authentication hash (one-way, from the master key)</td><td>❌ The AES encryption key / master key at rest</td></tr><tr><td>AES-256-GCM ciphertext + nonce + auth tag</td><td>❌ Any secret in plaintext</td></tr><tr><td>Hashed, single-use recovery codes</td><td>❌ Recovery codes in plaintext</td></tr><tr><td>Salted, hashed device passcode</td><td>❌ Passcodes in plaintext</td></tr></tbody></table><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to &quot;Reporting a vulnerability&quot;">​</a></h2><p>Please report suspected security issues privately via a GitHub security advisory rather than a public issue.</p>',16)])])}const y=t(i,[["render",s]]);export{u as __pageData,y as default};
